<?php require_once 'config.php';require_role('customer');$title='حجوزاتي';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['cancel']??0);$s=$pdo->prepare("UPDATE appointments SET status='cancelled' WHERE id=? AND customer_id=? AND status IN ('pending','confirmed') AND start_time>NOW()");$s->execute([$id,user()['id']]);if($s->rowCount()){$pdo->prepare("UPDATE payments SET payment_status='refunded' WHERE appointment_id=? AND payment_status='successful'")->execute([$id]);flash('تم إلغاء الحجز.');}else flash('تعذر إلغاء الحجز.');go('my_appointments.php');}$s=$pdo->prepare('SELECT ap.*,p.title,u.full_name provider_name,pm.payment_status FROM appointments ap JOIN provider_profiles p ON p.id=ap.provider_id JOIN users u ON u.id=p.user_id LEFT JOIN payments pm ON pm.appointment_id=ap.id WHERE ap.customer_id=? ORDER BY ap.start_time DESC');$s->execute([user()['id']]);$rows=$s->fetchAll();require 'includes/header.php';?><h1>حجوزاتي</h1><div class="tablewrap"><table><tr><th>مقدم الخدمة</th><th>الموعد</th><th>السعر</th><th>الحجز</th><th>الدفع</th><th>إجراء</th></tr><?php foreach($rows as $a):?><tr><td><?=h($a['title'])?> — <?=h($a['provider_name'])?></td><td><?=h($a['start_time'])?></td><td><?=number_format($a['consultation_price'],2)?> د.ل</td><td><?=h($a['status'])?></td><td><?=h($a['payment_status']??'—')?> (تجريبي)</td><td><?php if(in_array($a['status'],['pending','confirmed'])&&strtotime($a['start_time'])>time()):?><form method="post"><button class="btn" name="cancel" value="<?=$a['id']?>">إلغاء</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">لا توجد حجوزات حتى الآن.</td></tr><?php endif;?></table></div><?php require 'includes/footer.php';?>
